/**
 * Types for a small "requirement engine": a way to encode nested academic
 * requirements (degree / major / breadth requirements) as a tree, and to
 * evaluate that tree against a student's completed courses.
 *
 * Loosely modeled on the shape of real degree requirements at Berkeley (see
 * apps/docs/src/core/BtLL/README.md in the main Berkeleytime repo for the
 * production system this is inspired by). This is a simplified version for
 * the exercise -- not the real BtLL implementation.
 *
 * A requirement tree has two kinds of nodes:
 *
 *  - Leaves check something concrete against the student's completed
 *    courses: either a SPECIFIC course ("has the student taken COMPSCI
 *    61B?"), or a TAG ("has the student taken ANY course tagged
 *    'writing_intensive'?"). Tags model things like breadth designations,
 *    course attributes, etc.
 *
 *  - Internal nodes combine child requirements with AND / OR / "N of M"
 *    counting logic. A requirement tree can nest arbitrarily deep (e.g. an
 *    AND containing an OR containing an AND).
 */

export type CourseId = string; // e.g. "COMPSCI 61B"

/** Leaf: satisfied iff the student has completed this exact course. */
export interface CourseLeaf {
  type: "course";
  courseId: CourseId;
  /** Human-readable name, used when building "what's missing" explanations. */
  label?: string;
}

/** Leaf: satisfied iff the student has completed ANY course carrying this tag. */
export interface TagLeaf {
  type: "tag";
  tag: string;
  label?: string;
}

export type LeafNode = CourseLeaf | TagLeaf;

/** Satisfied iff EVERY child is satisfied. */
export interface AndNode {
  type: "and";
  label?: string;
  children: RequirementNode[];
}

/** Satisfied iff AT LEAST ONE child is satisfied. */
export interface OrNode {
  type: "or";
  label?: string;
  children: RequirementNode[];
}

/**
 * Satisfied iff at least `n` of the `children` are satisfied by DISTINCT
 * completed courses.
 *
 * The "distinct courses" part matters: if a single completed course happens
 * to satisfy two different children of the SAME n_of_m node (e.g. two of the
 * tag-leaves below both match one course the student took), that one course
 * must not be allowed to single-handedly cover two of the `n` slots. The
 * student still needs `n` distinct completed courses backing this node,
 * not just `n` satisfied child-nodes.
 *
 * (Contrast this with AND/OR: those never count "how many", so one course
 * satisfying two leaves under an AND or OR is completely fine.)
 */
export interface NOfMNode {
  type: "n_of_m";
  n: number;
  label?: string;
  children: RequirementNode[];
}

export type RequirementNode = LeafNode | AndNode | OrNode | NOfMNode;

export interface CompletedCourse {
  courseId: CourseId;
  /** Tags this course carries for this student's catalog year, e.g. breadth designations. */
  tags: string[];
}

export interface Student {
  name: string;
  completedCourses: CompletedCourse[];
}

/**
 * The result of evaluating a RequirementNode against a Student. Mirrors the
 * shape of the RequirementNode it came from, so callers (and tests) can walk
 * it to see not just "satisfied: true/false" at the root, but the status of
 * every node in the tree.
 */
export interface EvaluationResult {
  node: RequirementNode;
  satisfied: boolean;
  /**
   * Leaves only: the completed course id(s) that satisfy this leaf.
   * - CourseLeaf: either `[courseId]` (if completed) or `[]`.
   * - TagLeaf: every completed course carrying the tag (there may be more
   *   than one -- any single one would satisfy the leaf on its own).
   * Undefined for and/or/n_of_m nodes.
   */
  satisfiedBy?: CourseId[];
  /** and/or/n_of_m only: the evaluated result of each child, in order. */
  children?: EvaluationResult[];
}

/** A leaf that is not (yet) satisfied, surfaced for a "what do I still need" UI. */
export interface MissingLeaf {
  leaf: LeafNode;
  /**
   * Human-readable breadcrumb of ancestor labels down to this leaf, e.g.
   * "CS Major Requirements > 3 of 5 Upper-Division Electives". Falls back to
   * the node's `type` for any ancestor without a `label`.
   */
  path: string;
}
